@classmethod
def _check_ordering(cls):
    """
    Check "ordering" option -- is it a list of strings and do all fields
    exist?
    """
    if cls._meta._ordering_clash:
        return [
            checks.Error(
                "'ordering' and 'order_with_respect_to' cannot be used together.",
                obj=cls,
                id='models.E021',
            ),
        ]

    if cls._meta.order_with_respect_to or not cls._meta.ordering:
        return []

    if not isinstance(cls._meta.ordering, (list, tuple)):
        return [
            checks.Error(
                "'ordering' must be a tuple or list (even if you want to order by only one field).",
                obj=cls,
                id='models.E014',
            )
        ]

    errors = []
    fields = cls._meta.ordering

    # Skip expressions and '?' fields.
    fields = (f for f in fields if isinstance(f, str) and f != '?')

    # Convert "-field" to "field".
    fields = ((f[1:] if f.startswith('-') else f) for f in fields)

    # Separate related field paths from local field names.
    related_fields = []
    local_fields = []
    for field in fields:
        if LOOKUP_SEP in field:
            related_fields.append(field)
        else:
            local_fields.append(field)
    fields = local_fields

    for field in related_fields:
        model = cls
        fld = None
        for part in field.split(LOOKUP_SEP):
            try:
                if part == 'pk':
                    fld = model._meta.pk
                else:
                    fld = model._meta.get_field(part)
                model = fld.related_model if fld.is_relation else None
            except (FieldDoesNotExist, AttributeError):
                if fld is None or (
                    fld.get_transform(part) is None and fld.get_lookup(part) is None
                ):
                    errors.append(
                        checks.Error(
                            "'ordering' refers to the nonexistent field '%s'." % field,
                            obj=cls,
                            id='models.E015',
                        )
                    )
                break

    # Skip ordering on pk. This is always a valid order_by field
    # but is an alias and therefore won't be found by opts.get_field.
    fields = {f for f in fields if f != 'pk'}

    # Check for invalid or nonexistent fields in ordering.
    invalid_fields = []

    # Any field name that is not present in field_names does not exist.
    # Also, ordering by m2m fields is not allowed.
    opts = cls._meta
    valid_fields = set(chain.from_iterable(
        (f.name, f.attname) if not (f.auto_created and not f.concrete) else (f.field.related_query_name(),)
        for f in chain(opts.fields, opts.related_objects)
    ))

    invalid_fields.extend(fields - valid_fields)

    for invalid_field in invalid_fields:
        errors.append(
            checks.Error(
                "'ordering' refers to the nonexistent field '%s'." % invalid_field,
                obj=cls,
                id='models.E015',
            )
        )
    return errors

